108: // ─── Props ─────────────────────────────────────────────────────────────────
109: interface LoanFormProps {
110:   initialName?: string;
111:   initialMobile?: string;
112:   initialPan?: string;
113:   initialAmount?: number;
114:   initialPlan?: 'Daily' | 'Weekly';
115: }
116: 
117: export const LoanForm: React.FC<LoanFormProps> = ({
118:   initialName,
119:   initialMobile,
120:   initialPan,
121:   initialAmount,
122:   initialPlan,
123: }) => {
124:   const { language } = useLanguage();
125:   const isMr = language === 'mr';
126:   const isHi = language === 'hi';
127:   const navigate = useNavigate();
128: 
129:   // Retrieve saved session data if props not passed directly
130:   const savedName = initialName || (() => {
131:     try { return sessionStorage.getItem('befs_initial_name') || ''; } catch { return ''; }
132:   })();
133:   const savedMobile = initialMobile || (() => {
134:     try { return sessionStorage.getItem('befs_initial_mobile') || ''; } catch { return ''; }
135:   })();
136:   const savedPan = initialPan || (() => {
137:     try { return sessionStorage.getItem('befs_initial_pan') || ''; } catch { return ''; }
138:   })();
139: 
140:   const [currentStep, setCurrentStep] = useState(1);
141:   const [formErrors, setFormErrors] = useState<Record<string, string>>({});
142:   const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
143:   const [pdfBlobUrl, setPdfBlobUrl] = useState<string | null>(null);
144:   const [generatedPdfFileName, setGeneratedPdfFileName] = useState('');
145:   const [whatsAppDirectUrl, setWhatsAppDirectUrl] = useState('');
146:   const [statusMsg, setStatusMsg] = useState('');
147: 
148:   // Submitted application state
149:   const [isSubmitted, setIsSubmitted] = useState(false);
150:   const [hasOpenedWhatsApp, setHasOpenedWhatsApp] = useState(false);
151:   const [repayModalOpen, setRepayModalOpen] = useState(false);
152: 
153:   const [formData, setFormData] = useState<LoanFormData>(() => ({
154:     applicationNo: getOrCreateAppId(),
155:     fullName: savedName || '',
156:     fatherHusbandName: '',
157:     dob: '',
158:     mobileNumber: savedMobile || '',
159:     aadhaarNumber: '',
160:     panNumber: savedPan || '',
161:     fullAddress: '',
162:     businessName: '',
163:     typeOfBusiness: '',
164:     businessAddress: '',
165:     yearsInBusiness: '2',
166:     requiredLoanAmount: initialAmount ? initialAmount.toString() : '45000',
167:     purposeOfLoan: isMr
168:       ? 'व्यवसाय खेळते भांडवल / दुकान विस्तार'
169:       : isHi
170:       ? 'व्यावसायिक कार्यशील पूंजी / दुकान विस्तार'
171:       : 'Business Working Capital / Shop Expansion',
172:     repaymentPlan: initialPlan || 'Daily',
173:     guarantorName: '',
174:     guarantorMobile: '',
175:     guarantorAddress: '',
176:     guarantorRelation: '',
177:     docAadhaar: true,
178:     docPan: true,
179:     docPhoto: true,
180:     docBusinessProof: true,
181:     declarationAccepted: false,
182:     applicantSignature: '',
183:     signatureType: 'draw',
184:     applicationDate: new Date().toLocaleDateString('en-GB'),
185:   }));
186: 
187:   useEffect(() => {
188:     if (initialName) setFormData(prev => ({ ...prev, fullName: initialName }));
189:     if (initialMobile) setFormData(prev => ({ ...prev, mobileNumber: initialMobile }));
190:     if (initialPan) setFormData(prev => ({ ...prev, panNumber: initialPan }));
191:     if (initialAmount) setFormData(prev => ({ ...prev, requiredLoanAmount: initialAmount.toString() }));
192:     if (initialPlan) setFormData(prev => ({ ...prev, repaymentPlan: initialPlan }));
193:   }, [initialName, initialMobile, initialPan, initialAmount, initialPlan]);
194: 
195:   const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
196:     const { name, value, type } = e.target;
197:     const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
198:     setFormData(prev => ({ ...prev, [name]: val }));
199:     if (formErrors[name]) setFormErrors(prev => { const u = { ...prev }; delete u[name]; return u; });
200:   };
201: 
202:   const handleSignatureChange = (sig: string, type: 'draw' | 'type') => {
203:     setFormData(prev => ({ ...prev, applicantSignature: sig, signatureType: type }));
204:     if (formErrors.applicantSignature) setFormErrors(prev => { const u = { ...prev }; delete u.applicantSignature; return u; });
205:   };
206: 
207:   // ── Validate current step ────────────────────────────────────────────────
208:   const validateStep = (step: number): boolean => {
209:     const errors: Record<string, string> = {};
210: 
211:     // STEP 1: Personal Details
212:     if (step === 1) {
213:       if (!formData.fullName.trim()) errors.fullName = isMr ? 'पूर्ण नाव आवश्यक आहे' : isHi ? 'पूरा नाम अनिवार्य है' : 'Full name is required';
214:       if (!formData.fatherHusbandName.trim()) errors.fatherHusbandName = isMr ? 'वडिलांचे / पतीचे नाव आवश्यक आहे' : isHi ? 'पिता / पति का नाम अनिवार्य है' : 'Father / Husband name is required';
215:       if (!formData.dob) errors.dob = isMr ? 'जन्मतारीख आवश्यक आहे' : isHi ? 'जन्म तिथि अनिवार्य है' : 'Date of birth is required';
216:       if (!formData.mobileNumber.trim() || formData.mobileNumber.length < 10)
217:         errors.mobileNumber = isMr ? 'वैध १० अंकी मोबाइल नंबर आवश्यक आहे' : isHi ? 'मान्य १० अंकों का मोबाइल नंबर अनिवार्य है' : 'Valid 10-digit mobile is required';
218:       if (!formData.aadhaarNumber.trim() || formData.aadhaarNumber.replace(/\s+/g, '').length < 12)
219:         errors.aadhaarNumber = isMr ? '१२ अंकी आधार कार्ड नंबर आवश्यक आहे' : isHi ? '१२ अंकों का आधार नंबर अनिवार्य है' : 'Valid 12-digit Aadhaar number is required';
220: 
221:       const panRegex = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/;
222:       if (!formData.panNumber.trim()) {
223:         errors.panNumber = isMr ? 'पॅन नंबर आवश्यक आहे' : isHi ? 'पैन नंबर अनिवार्य है' : 'PAN number is required';
224:       } else if (formData.panNumber.length !== 10 || !panRegex.test(formData.panNumber)) {
225:         errors.panNumber = isMr ? 'वैध १० अंकी पॅन कार्ड आवश्यक (उदा. ABCDE1234F)' : isHi ? 'मान्य १० अक्षरों का पैन कार्ड आवश्यक (उदा. ABCDE1234F)' : 'Valid 10-character PAN required (e.g. ABCDE1234F)';
226:       }
227:       if (!formData.fullAddress.trim()) errors.fullAddress = isMr ? 'रहिवासी पत्ता आवश्यक आहे' : isHi ? 'आवासीय पता अनिवार्य है' : 'Residential address is required';
228:     }
229: 
230:     // STEP 2: Business Info
231:     if (step === 2) {
232:       if (!formData.businessName.trim()) errors.businessName = isMr ? 'व्यवसायाचे नाव आवश्यक आहे' : isHi ? 'व्यवसाय का नाम अनिवार्य है' : 'Business name is required';
233:       if (!formData.typeOfBusiness.trim()) errors.typeOfBusiness = isMr ? 'व्यवसाय प्रकार आवश्यक आहे' : isHi ? 'व्यवसाय का प्रकार अनिवार्य है' : 'Type of business is required';
234:       if (!formData.businessAddress.trim()) errors.businessAddress = isMr ? 'व्यवसायाचा पत्ता आवश्यक आहे' : isHi ? 'व्यवसाय का पता अनिवार्य है' : 'Business address is required';
235:     }
236: 
237:     // STEP 3: Loan Details
238:     if (step === 3) {
239:       if (!formData.requiredLoanAmount) errors.requiredLoanAmount = isMr ? 'कर्ज रक्कम निवडा' : isHi ? 'ऋण राशि चुनें' : 'Loan amount is required';
240:       if (!formData.repaymentPlan) errors.repaymentPlan = isMr ? 'परतफेड योजना निवडा' : isHi ? 'पुनर्भुगतान योजना चुनें' : 'Select a repayment plan';
241:     }
242: 
243:     // STEP 4: Guarantor Details (Compulsory)
244:     if (step === 4) {
245:       if (!formData.guarantorName.trim()) errors.guarantorName = isMr ? 'जामीनदाराचे पूर्ण नाव आवश्यक आहे' : isHi ? 'गारंटर का पूरा नाम अनिवार्य है' : 'Guarantor full name is required';
246:       if (!formData.guarantorMobile.trim() || formData.guarantorMobile.length < 10)
247:         errors.guarantorMobile = isMr ? 'जामीनदाराचा वैध १० अंकी मोबाइल आवश्यक आहे' : isHi ? 'गारंटर का मान्य १० अंकों का मोबाइल नंबर अनिवार्य है' : 'Valid 10-digit guarantor mobile is required';
248:       if (!formData.guarantorRelation.trim()) errors.guarantorRelation = isMr ? 'नातेसंबंध आवश्यक आहे' : isHi ? 'गारंटर से संबंध अनिवार्य है' : 'Relation with guarantor is required';
249:       if (!formData.guarantorAddress.trim()) errors.guarantorAddress = isMr ? 'जामीनदाराचा पत्ता आवश्यक आहे' : isHi ? 'गारंटर का पता अनिवार्य है' : 'Guarantor address is required';
250:     }
